import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import Container from 'react-bootstrap/Container';
import Row from 'react-bootstrap/Row';
import Col from 'react-bootstrap/Col';
import { useNavigate } from 'react-router-dom';
import axios from "axios"; 
import Comment from "./Comment"; 
import NavigationBar from './NavigationBar';
import PostForm from './CreatePost';

const PostDetail = () => {
    const { postId } = useParams(); 
    const [post, setPost] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [editingPost, setEditingPost] = useState(null);
    const userId = localStorage.getItem('userId');
    const token = localStorage.getItem("authToken");
    const navigate = useNavigate();

      const fetchPost = async () => {
            try {
                const token = localStorage.getItem("authToken");
                const response = await axios.get(`http://localhost:6543/api/posts/${postId}`, {
                  headers: { Authorization: `Bearer ${token}` }
                });
                setPost(response.data);
            } catch (err) {
                setError("Post not found.");
            } finally {
                setLoading(false);
            }
        };

    useEffect(() => {
        fetchPost();
    }, [postId]);

    const handleDelete = async (postId) => {
      try {
        await axios.delete(`http://localhost:6543/api/posts/${postId}/delete`, {
          headers: { Authorization: `Bearer ${token}`,
          "Content-Type": "application/json", },
          withCredentials: true,
        });
        alert("Post deleted successfully!");
        navigate("/home");
      } catch (error) {
        console.error("Error deleting post:", error);
        alert("Failed to delete post.");
      }
    };
  
    const handleEdit = (post) => {
      if (Number(userId) !== post.user.id) {
        alert("You are not authorized to edit this post.");
        return;
      }
      setEditingPost(post);
    };
  
    const handleUpdateComplete = () => {
      setEditingPost(null);
      fetchPost();
    };

    if (loading) return <p>Loading...</p>;
    if (error) return <p>{error}</p>;

    return (
        <div fluid>
          <NavigationBar />
          <Container style={{ width: "100%", paddingTop: "1.5rem" }}>
            <Row>
              <Col style={{ paddingBottom: "1.5rem" }}>
              <Link to="/home">Back</Link>
                <h2>{post.user.username}'s Post</h2>
                <p>{post.content}</p>
                {Number(userId) === post.user.id && (
                        <div>
                          <button onClick={() => handleEdit(post)}>Edit</button>
                          <button onClick={() => handleDelete(post.id, post.user.id)}>Delete</button>
                        </div>
                  )}
                  {editingPost && editingPost.id === post.id && (
                        <PostForm post={editingPost} refreshPosts={handleUpdateComplete} cancelEdit={() => setEditingPost(null)}/>
                  )}
                <Comment postId={post.id} user={{ id: localStorage.getItem("userId") }} />
              </Col>
            </Row>
          </Container>
        </div>
    );
};

export default PostDetail;
